gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

class Combination:
    def __init__(self, n, k):
        self.n = n
        self.k = k
        self.gsl_combination = ctypes.py_object()
        self.gsl_combination_ptr = ctypes.c_void_p(None)
        self.init(n, k)

    def init(self, n, k):
        self.n = n
        self.k = k
        self.gsl_combination_ptr = gsl.gsl_combination_alloc(ctypes.c_size_t(self.n), ctypes.c_size_t(self.k))
        if self.gsl_combination_ptr is None:
            return None
        self.gsl_combination = ctypes.py_object()
        self.gsl_combination._obj = self.gsl_combination_ptr

    def free(self):
        if self.gsl_combination_ptr is not None:
            gsl.gsl_combination_free(self.gsl_combination_ptr)
            self.gsl_combination_ptr = ctypes.c_void_p(None)

    def create_first_combination(self, n, k):
        result = [0] * (n+1)
        for i in range(k+1):
            for j in range(i, k+1):
                result[j] += 1
        return result

def generate_combination(n, k):
    comb = Combination(n, k)
    if comb is None:
        return json.dumps({"Candidate_solution": "Failed to allocate combination."})
    comb.init(n, k)
    result = comb.create_first_combination(n, k)
    comb.free()
    return json.dumps({"Candidate_solution": str(result)})

