def compute_legendre_derivatives(x, l):
    assert x >= -1 and x <= 1
    assert l >= 0
    if l == 0:
        return [x, 1, 0]
    elif l == 1:
        return [x, 2*x, 2]
    else:
        result = [[], [], []]
        for i in range(l+1):
            if i < l//2 or i > l//2 + (l%2):
                P_lm = 0
            elif i == l//2 and l%2 == 0:
                P_lm = factorial(2*l)/factorial(i)/factorial(l-i)
            else:
                P_lm = factorial(2*l)/(2*fact.factorial(i)*factorial(l-i))
                if i > l//2 - (l%2):
                    P_lm *= -1
                result[0].append(x)
                result[1].append(P_lm)
                result[2].append(-(2*i+1)*P_lm/(x**2-1))
        return [i for i in zip(*result)]

