        self.rows = rows
        self.cols = cols

    @staticmethod
    def alloc(rows, cols):
        return gsl.gsl_matrix_alloc(rows, cols)

    @staticmethod
    def free(matrix):
        return gsl.gsl_matrix_free(matrix)

    @staticmethod
    def numpy_to_gsl(np_array):
        matrix = GSLMatrix.alloc(*np_array.shape)
        for i in range(len(np_array)):
            for j in range(len(np_array[i])):
                ctypes.c_double.from_param(matrix[i, j]) = np_array[i, j]
        return matrix

    @staticmethod
    def gsl_to_numpy(gsl_matrix):
        rows = [ctypes.c_double(*[0] * len(gsl_matrix))]
        cols = [ctypes.c_double(*[0] * len(gsl_matrix))]
        for i in range(len(gsl_matrix)):
            row = []
            for j in range(len(gsl_matrix[i])):
                row.append(ctype.c_double.from_param(gsl_matrix[i, j]))
            rows.append(row)
        return np.array(rows)

    def gsl_multifit_covar(self, jacobian, epsrel):
        result = GSLMatrix.alloc(self.rows, self.cols)
        error = ctypes.c_int(0)
        gsl.gsl_multifit_covar(jacobian, epsrel, result, byref(error))
        if error.value != 0:
