import ctypes
import json
from ctypes.util import find_library

gsl = ctypes.CDLL(find_library('gsl'), mode=ctypes.RTLD_GLOBAL)
cblas = ctypes.CDLL(find_library('gslcblas'), mode=ctypes.RTLD_GLOBAL)

class gsl_matrix(ctypes.Structure):
    _fields_ = [('data', ctypes.POINTER(ctypes.c_double))]

class gsl_vector_complex(ctypes.Structure):
    _fields_ = [('data', ctypes.POINTER(ctypes.c_float*2)])

class gsl_eigen_nonsymm_workspace(ctypes.Structure):
    _fields_ = [('work', ctypes.POINTER(None)])

def create_gsl_matrix(matrix):
    n = len(matrix)
    m = len(matrix[0])
    mat_data = (ctypes.c_double * (n*m))()
    for i in range(n):
        for j in range(m):
            mat_data[i*m + j] = matrix[i][j]
    return gsl_matrix.from_address(mat_data.__repr__().encode('utf-8'))

def create_gsl_vector_complex(size):
    vec_data = (ctypes.c_float*2 * size)()
    for i in range(size):
        vec_data[i] = 0.0, 0.0
    return gsl_vector_complex.from_address(vec_data.__repr__().encode('utf-8'))

def compute_eigenvalues_nonsymm(matrix):
    workspace = gsl_eigen_nonsymm_workspace()
    result = (ctypes.c_double * len(matrix))()
    eigenvalues = (ctypes.c_float*2 * len(matrix))()
    for i in range(len(matrix)):
        cblas.gsl_eigen_nonsymm(workspace, create_gsl_matrix(matrix), create_gsl_vector_complex(len(matrix)), result, eigenvalues)
    return json.dumps([complex(*eigenvalue) for eigenvalue in [tuple(eigenvalues[i:i+2]) for i in range(0, len(matrix)*2, 2)]])

