import numpy as np
from typing import List, Tuple
def create_gsl_matrix(matrix: List[List[float]]) -> object:
    matrix_ptr = ctypes.POINTER(ctypes.c_double * len(matrix))(*([ctypes.c_double]*len(matrix))*[list(row) for row in matrix])
    return matrix_ptr

class gsl_matrix(object):
    def __init__(self, data: List[List[float]]) -> None:
        self.data = create_gsl_matrix(data)

def create_gsl_vector_complex(size: int) -> object:
    return ctypes.POINTER(ctypes.c_double * size)

def compute_eigenvalues_nonsymm(matrix: gsl_matrix, size: int) -> List[complex]:
    matrix_ptr = matrix.data
    c_size = ctypes.c_int(size)
    eigenvalues_ptr = ctypes.POINTER(ctypes.c_double * size)
    workspace_ptr = ctypes.POINTER(None)
    c_eigenvalues_ptr = ctypes.pointer(eigenvalues_ptr)
    gsl.gsl_eigen_nonsymm_workspace_create.restype = ctypes.POINTER(None)
    workspace_ptr = gsl.gsl_eigen_nonsymm_workspace_create()
    try:
        gsl.gsl_eigen_nonsymm(matrix_ptr, c_size, c_eigenvalues_ptr, workspace_ptr)
    finally:
        if workspace_ptr is not None:
            workspace = ctypes.POINTER(None)(workspace_ptr)
            if workspace.contents != None:
                import gc
                gc.collect()
                del workspace
    eigenvalues_list = [complex(c_eigenvalues_ptr[i]/(1<<31), c_eigenvalues_ptr[i]%((1<<31)-1))/1e6 for i in range(size)]
    return list(map(lambda x: complex(x.real, x.imag), eigenvalues_list))

