            for j in range(gsl_matrix.get_col_size()):
                matrix[i][j] = gslcblas.gsl_matrix_get(gsl_matrix, i, j)
        return cls(matrix)

    def __del__(self):
        if hasattr(self, 'matrix') and self.matrix is not None:
            np.delete(self.matrix)
        if hasattr(self, 'gsl_matrix') and self.gsl_matrix is not None:
            gslcblas.gsl_matrix_free(self.gsl_matrix)

