class GSLSpMatrix:
    def __init__(self):
        self.matrix_ptr = None

    def create_sparse_matrix(self, size):
        self.matrix_ptr = gsl.spmatrix_alloc(size, size)

    def set_sparse_matrix_element(self, row, col, value):
        if not isinstance(value, (int, float)):
            raise ValueError("value must be int or float")
        if value is None:
            return
        c_row = ctypes.c_int(row)
        c_col = ctypes.c_int(col)
        c_value = ctypes.c_double(value) if isinstance(value, float) else ctypes.c_long(value)
        gsl.spmatrix_set(self.matrix_ptr, c_row, c_col, c_value)

    def get_sparse_matrix_elements(self):
        if self.matrix_ptr is None:
            return []
        rows = []
        cols = []
        values = []
        for i in range(gsl.spmatrix_get_size1(self.matrix_ptr)):
            for j in range(gsl.spmatrix_get_size2(self.matrix_ptr)):
                val = gsl.spmatrix_get(self.matrix_ptr, i, j)
                if val != 0:
                    rows.append(i)
                    cols.append(j)
                    values.append(val)
        return list(zip(rows, cols, values))

    def swap_sparse_matrix_elements(self, i, j):
        if self.matrix_ptr is None:
            raise ValueError("Sparse matrix not initialized")
        c_i = ctypes.c_int(i)
        c_j = ctypes.c_int(j)
        gsl.spmatrix_swap(self.matrix_ptr, c_i, c_j)

