def create_histogram2d(nx, ny, xrange, yrange):
    if not isinstance(nx, int) or nx <= 0:
        return "Invalid nx value"
    if not isinstance(ny, int) or ny <= 0:
        return "Invalid ny value"
    if not all(isinstance(x, float) for x in xrange) or len(xrange) != nx:
        return "xrange must be a list of length nx with increasing values"
    if not all(isinstance(y, float) for y in yrange) or len(yrange) != ny:
        return "yrange must be a list of length ny with increasing values"

    gsl_histogram2d = c_void_p()
    create_histogram2d_cfunc = libgsl.gsl_histogram2d_calloc_range
    create_histogram2d_cfunc.argtypes = [c_int, c_int, POINTER(c_double), POINTER(c_double)]
    create_histogram2d_cfunc.restype = c_void_p

    gsl_histogram2d = create_histogram2d_cfunc(nx, ny, (c_double * len(xrange))(*xrange), (c_double * len(yrange))(*yrange))

    if gsl_histogram2d == None:
        return "Error allocating histogram"

