class GslRstatQuantileWorkspace:
    def __init__(self):
        self.workspace = None

    def compute_quantile(self, p, values):
        if not self.workspace:
            self.workspace = self._allocate()
        if self._is_zero_length(values):
            return None
        for value in values:
            self._add(value)
        quantile = self._get(p)
        self._free()
        return quantile

    def _allocate(self):
        libgsl_rstat_quantile_alloc.restype = ctypes.c_void_p
        libgsl_rstat_quantile_alloc.argtypes = [ctypes.c_size_t]
        return libgsl_rstat_quantile_alloc(ctypes.sizeof(ctypes.c_double))

    def _reset(self):
        libgsl_rstat_quantile_reset.argtypes = [self.workspace]
        libgsl_rstat_quantile_reset.restype = ctypes.c_int
        libgsl_rstat_quantile_reset(self.workspace)

    def _add(self, value):
        libgsl_rstat_quantile_add.argtypes = [self.workspace, ctypes.c_double]
        libgsl_rstat_quantile_add(self.workspace, value)

    def _get(self, p):
        libgsl_rstat_quantile_get.argtypes = [self.workspace, ctypes.c_double, ctypes.POINTER(ctypes.c_double)]
        result = ctypes.c_double(0)
        libgsl_rstat_quantile_get(self.workspace, p, ctypes.byref(result))
        return result.value

    def _free(self):
        libgsl_rstat_quantile_free.argtypes = [self.workspace]
        libgsl_rstat_quantile_free(self.workspace)

    @staticmethod
    def _is_zero_length(values):
        return len(values) == 0


