class GslRstatQuantileWorkspace:
    def __init__(self):
        self.workspace = None

    def allocate(self):
        self.workspace = ctypes.c_void_p()
        return self.workspace

    def reset(self, workspace):
        self.workspace = workspace
        return self.workspace

    def add_values(self, workspace, values):
        c_values = (ctypes.c_double * len(values))(*values)
        func = getattr(gsl.rstat_quantile, 'gsl_rstat_quantile_add')
        func(workspace, ctypes.c_int(len(c_values)), c_values)
        return self.workspace

    def get_quantile(self, workspace, p):
        c_p = ctypes.c_double(p)
        result = ctypes.c_double()
        func = getattr(gsl.rstat_quantile, 'gsl_rstat_quantile_get')
        func(workspace, c_p, result)
        return float(result)

    def free(self, workspace):
        func = getattr(gsl.rstat_quantile, 'gsl_rstat_quantile_free')
        func(workspace)
        self.workspace = None

