            raise ValueError('Workspace not allocated')
        return_value = ctypes.c_double(0.0)
        gsl.gsl_rstat_quantile_get.restype = ctypes.c_double
        result = gsl.gsl_rstat_quantile_get(self.workspace, ctypes.byref(return_value), p)
        if result < 0:
            raise ValueError('Invalid quantile index')
        return return_value.value

    def free(self):
        if self.workspace is None:
            return
        gsl.gsl_rstat_quantile_free(self.workspace)
